<?php
declare(strict_types=1);
require_once __DIR__ . '/../config/bootstrap.php';
require_once __DIR__ . '/../config/admin_auth.php';
brvtal_admin_require();
?>
<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>BRVTAL / CONTENT CORE</title>
<style>
:root{--bg:#050505;--panel:#090a0b;--line:#292d31;--muted:#737980;--text:#f4f5f6;--red:#ff2038;--green:#49d98a}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font-family:Arial,Helvetica,sans-serif}button,input,textarea,select{font:inherit}button{cursor:pointer}.wrap{max-width:1500px;margin:auto;padding:28px}.head{display:flex;justify-content:space-between;align-items:flex-end;border-bottom:1px solid var(--line);padding-bottom:18px}.ey{font-size:9px;letter-spacing:2.5px;color:var(--muted)}h1{font-size:34px;letter-spacing:-1.5px;margin:6px 0 0}.head-actions{display:flex;gap:8px}.btn{border:1px solid #34393e;background:transparent;color:#fff;padding:11px 15px;font-weight:800}.btn.red{background:var(--red);border-color:var(--red)}.btn.green{border-color:#2d6e50;color:var(--green)}.tabs{display:flex;gap:4px;margin:22px 0}.tab{border:1px solid var(--line);background:#090a0b;color:#777;padding:10px 15px;font-size:10px;letter-spacing:1.5px}.tab.active{color:#fff;border-color:#555}.panel{border:1px solid var(--line);background:var(--panel);padding:18px}.toolbar{display:flex;gap:10px;justify-content:space-between;margin-bottom:12px}.search{background:#050606;border:1px solid #34393e;color:#fff;padding:11px;width:min(400px,100%)}.table{border:1px solid var(--line)}.tr,.th{display:grid;grid-template-columns:2fr 1fr 1fr 120px;gap:12px;align-items:center;padding:13px 14px}.th{font-size:9px;letter-spacing:1.5px;color:#666d73;background:#0d0f10}.tr{font-size:12px;border-top:1px solid #1d2023}.title{font-weight:800}.meta{font-size:10px;color:var(--muted);margin-top:4px}.pill{display:inline-block;border:1px solid #383d42;padding:5px 7px;font-size:9px;text-transform:uppercase}.actions{display:flex;justify-content:flex-end;gap:6px}.icon{border:1px solid #34393e;background:#111315;color:#fff;padding:7px 9px;font-size:10px}.empty{padding:50px;text-align:center;color:#686f75}.form{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.field label{display:block;color:#8b9197;font-size:9px;text-transform:uppercase;letter-spacing:1.4px;margin-bottom:7px}.field input,.field textarea,.field select{width:100%;background:#050606;border:1px solid #353a3f;color:#fff;padding:11px}.field textarea{min-height:105px;resize:vertical}.full{grid-column:1/-1}.box{border:1px solid #24282c;background:#0a0b0c;padding:15px}.box h3{font-size:10px;letter-spacing:2px;margin:0 0 12px;color:#a4aab0}.notice{margin:0 0 12px;padding:10px;border:1px solid #34393e;font-size:11px;display:none}.notice.show{display:block}.notice.ok{color:var(--green);border-color:#2d6e50}.notice.err{color:#ff6666}.wizard{display:grid;grid-template-columns:190px 1fr;gap:15px}.steps{border:1px solid var(--line);background:#080909}.step{padding:14px;border-bottom:1px solid #202428;color:#686f75;font-size:10px;letter-spacing:1.2px}.step:last-child{border-bottom:0}.step.active{color:#fff;border-left:3px solid var(--red);padding-left:11px}.step.done{color:var(--green)}.wizard-main{min-width:0}.step-content{display:none}.step-content.active{display:block}.section{border:1px solid var(--line);background:#090a0b;padding:17px;margin-bottom:12px}.sectionhead{display:flex;justify-content:space-between;gap:10px;border-bottom:1px solid #24282c;padding-bottom:11px;margin-bottom:15px}.sectionhead strong{font-size:10px;letter-spacing:1.8px}.helper{font-size:10px;color:#747b82;line-height:1.5}.foot{display:flex;justify-content:space-between;gap:8px;border-top:1px solid #24282c;padding-top:15px;margin-top:15px}.foot-right{display:flex;gap:7px}.ticket-row{display:grid;grid-template-columns:1.2fr .8fr .65fr 1.3fr 90px;gap:7px;margin-bottom:7px}.ticket-row input,.ticket-row select{background:#050606;border:1px solid #353a3f;color:#fff;padding:9px}.roster{display:grid;grid-template-columns:1fr 1fr;gap:15px}.artist-list{max-height:560px;overflow:auto}.artist{display:flex;align-items:center;gap:10px;border:1px solid #25292d;background:#0d0f10;padding:10px;margin-bottom:7px}.artist img,.ph{width:46px;height:46px;object-fit:cover;background:#111;border:1px solid #30353a}.ph{display:grid;place-items:center;color:#555;font:9px monospace}.artist .grow{min-width:0;flex:1}.artist b{font-size:12px}.artist small{display:block;color:#6f767c;margin-top:4px}@media(max-width:850px){.wrap{padding:16px}.head{align-items:flex-start;gap:12px}.head-actions{flex-wrap:wrap}.wizard,.roster{grid-template-columns:1fr}.form{grid-template-columns:1fr}.full{grid-column:auto}.th{display:none}.tr{grid-template-columns:1fr 1fr}.tr>div:nth-child(2),.tr>div:nth-child(3){display:none}.ticket-row{grid-template-columns:1fr 1fr}.ticket-row input:nth-child(4),.ticket-row select:nth-child(3){grid-column:span 2}}
</style>
</head>
<body>
<div class="wrap">
<header class="head"><div><div class="ey">BRVTAL / DISCADMIN</div><h1>CONTENT CORE</h1></div><div class="head-actions"><button class="btn" onclick="location.href='/discadmin/'">← DISCADMIN</button><button class="btn green" onclick="openEvent()">+ NEW EVENT</button></div></header>
<div id="notice" class="notice"></div>
<div class="tabs"><button class="tab active" data-tab="events">EVENT EDITOR</button><button class="tab" data-tab="roster">COLLECTIVE ROSTER</button></div>
<section id="eventsTab" class="panel"><div class="toolbar"><input id="eventSearch" class="search" placeholder="Search events…"><button class="btn" onclick="loadEvents()">REFRESH</button></div><div id="eventsTable" class="table"></div></section>
<section id="rosterTab" class="panel" style="display:none"><div class="toolbar"><input id="artistSearch" class="search" placeholder="Search artists…"><button class="btn" onclick="loadArtists()">REFRESH</button></div><div class="roster"><div class="box"><h3>COLLECTIVE ROSTER</h3><div class="helper">Manage active BRVTAL DJs and alumni without changing the artist identity itself.</div><div id="rosterList" class="artist-list" style="margin-top:12px"></div></div><div class="box"><h3>ARTIST LIFECYCLE</h3><div id="artistDetail" class="helper">Select an artist to edit collective status and order.</div></div></div></section>
</div>
<div id="eventModal" class="modal"><div class="modalbox"><div class="modalhead"><div><div class="ey">CONTENT CORE / EVENT</div><h2 id="eventHeading">NEW EVENT</h2></div><button class="icon" onclick="closeEvent()">CLOSE</button></div><div id="eventNotice" class="notice"></div><div class="wizard"><div class="steps"><div class="step active" data-step="1">01 · IDENTITY</div><div class="step" data-step="2">02 · DATE & PLACE</div><div class="step" data-step="3">03 · LIFECYCLE</div><div class="step" data-step="4">04 · TICKETS</div><div class="step" data-step="5">05 · ROSTER</div></div><div class="wizard-main">
<form id="eventForm" onsubmit="return false">
<div class="step-content active" data-content="1"><div class="section"><div class="sectionhead"><strong>EVENT IDENTITY</strong><span class="helper">Save incomplete content at any time.</span></div><div class="form"><div class="field"><label>Name *</label><input id="e_title"></div><div class="field"><label>Slug</label><input id="e_slug" placeholder="Generated automatically"></div><div class="field full"><label>Description</label><textarea id="e_description"></textarea></div><div class="field"><label>Cover image</label><input id="e_cover_image" placeholder="Media path / URL"></div><div class="field"><label>Accent</label><input id="e_accent" placeholder="#ff2038"></div><div class="field"><label>Featured</label><select id="e_featured"><option value="0">No</option><option value="1">Yes</option></select></div></div></div></div>
<div class="step-content" data-content="2"><div class="section"><div class="sectionhead"><strong>DATE & PLACE</strong></div><div class="form"><div class="field"><label>Date & time *</label><input id="e_event_date" type="datetime-local"></div><div class="field"><label>City *</label><input id="e_city"></div><div class="field"><label>Venue</label><input id="e_venue"></div><div class="field"><label>Archive year</label><input id="e_archive_year" type="number" min="2000" max="2200"></div></div></div></div>
<div class="step-content" data-content="3"><div class="section"><div class="sectionhead"><strong>LIFECYCLE</strong></div><div class="form"><div class="field"><label>Status</label><select id="e_status"><option>draft</option><option>published</option><option>upcoming</option><option>tickets_available</option><option>last_tickets</option><option>sold_out</option><option>cancelled</option><option>finished</option><option>archived</option></select></div><div class="field"><label>Ticket instructions</label><textarea id="e_ticket_instructions"></textarea></div><div class="field"><label>Ticket QR</label><input id="e_ticket_qr"></div><div class="field"><label>External ticket URL</label><input id="e_ticket_url"></div></div></div></div>
<div class="step-content" data-content="4"><div class="section"><div class="sectionhead"><strong>TICKET TYPES</strong><button type="button" class="btn" onclick="addTicket()">+ ADD TICKET</button></div><div class="helper" style="margin-bottom:12px">No purchaser or attendee data is stored. Each type can point to an external payment/ticket destination.</div><div id="tickets"></div></div></div>
<div class="step-content" data-content="5"><div class="section"><div class="sectionhead"><strong>BRVTAL COLLECTIVE / EVENT PARTICIPATION</strong></div><div class="helper" style="margin-bottom:12px">This is the event roster. It does not redefine the artist's collective history.</div><div id="eventArtists" class="artist-list"></div></div></div>
</form><div class="foot"><button class="btn" onclick="closeEvent()">CANCEL</button><div class="foot-right"><button id="prevBtn" class="btn" onclick="step(-1)">← BACK</button><button id="nextBtn" class="btn" onclick="step(1)">NEXT →</button><button id="saveBtn" class="btn red" onclick="saveEvent()">SAVE DRAFT</button></div></div>
</div></div></div></div>
<script>
const API=['/api/index.php','/api/public'];let events=[],artists=[],currentEvent=null,currentStep=1,csrf='';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
async function api(path,opts={}){let last;for(const base of API){try{const r=await fetch(base+path,{credentials:'same-origin',headers:{'Content-Type':'application/json',...(opts.headers||{})},...opts});const j=await r.json();if(r.status===401){location.href='/discadmin/';return j}if(r.ok||j)return j;}catch(e){last=e}}throw last||new Error('API unavailable')}
function msg(text,ok=true,target='notice'){const n=$('#'+target);n.textContent=text;n.className='notice show '+(ok?'ok':'err');setTimeout(()=>n.classList.remove('show'),5000)}
function esc(v){return String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
async function initAuth(){const j=await api('/auth');if(!j.authenticated){location.href='/discadmin/';return}csrf=j.csrf||'';if(!csrf)throw new Error('CSRF token unavailable')}
async function loadEvents(){try{const j=await api('/events');events=j.data||j.events||[];renderEvents()}catch(e){msg('Could not load events: '+e.message,false)}}
function renderEvents(){const q=($('#eventSearch').value||'').toLowerCase();const a=events.filter(x=>JSON.stringify(x).toLowerCase().includes(q));$('#eventsTable').innerHTML='<div class="th"><div>EVENT</div><div>DATE</div><div>STATUS</div><div></div></div>'+(a.length?a.map(x=>`<div class="tr"><div><div class="title">${esc(x.title||x.name)}</div><div class="meta">${esc(x.city||'')} ${x.venue?'· '+esc(x.venue):''}</div></div><div>${esc(x.event_date||'—')}</div><div><span class="pill">${esc(x.status||'draft')}</span></div><div class="actions"><button class="icon" onclick="openEvent(${Number(x.id)})">EDIT</button></div></div>`).join(''):'<div class="empty">No events found.</div>')}
function fill(id,v){const el=$('#'+id);if(el)el.value=v??''}
function openEvent(id=null){currentEvent=events.find(x=>Number(x.id)===Number(id))||null;$('#eventHeading').textContent=currentEvent?'EDIT EVENT':'NEW EVENT';fill('e_title',currentEvent?.title);fill('e_slug',currentEvent?.slug);fill('e_description',currentEvent?.description);fill('e_cover_image',currentEvent?.cover_image);fill('e_accent',currentEvent?.accent);fill('e_featured',currentEvent?.featured?'1':'0');fill('e_event_date',currentEvent?.event_date?String(currentEvent.event_date).replace(' ','T').slice(0,16):'');fill('e_city',currentEvent?.city);fill('e_venue',currentEvent?.venue);fill('e_archive_year',currentEvent?.archive_year);fill('e_status',currentEvent?.status||'draft');fill('e_ticket_instructions',currentEvent?.ticket_instructions);fill('e_ticket_qr',currentEvent?.ticket_qr);fill('e_ticket_url',currentEvent?.ticket_url);$('#tickets').innerHTML='';(currentEvent?.ticket_types||[]).forEach(addTicket);renderEventArtists();currentStep=1;setStep();$('#eventModal').classList.add('open')}
function closeEvent(){
  $('#eventModal').classList.remove('open');
}
function step(dir){if(dir>0&&currentStep===1&&!$('#e_title').value.trim()){msg('Event name is required before continuing.',false,'eventNotice');return}currentStep=Math.max(1,Math.min(5,currentStep+dir));setStep()}
function setStep(){$$('.step').forEach(x=>x.classList.toggle('active',Number(x.dataset.step)===currentStep));$$('.step-content').forEach(x=>x.classList.toggle('active',Number(x.dataset.content)===currentStep));$('#prevBtn').style.visibility=currentStep===1?'hidden':'visible';$('#nextBtn').style.display=currentStep===5?'none':'inline-block';$('#saveBtn').textContent=currentStep===5?'SAVE EVENT':'SAVE DRAFT'}
function addTicket(t={}){const d=document.createElement('div');d.className='ticket-row';if(t.id)d.dataset.id=String(t.id);d.innerHTML=`<input data-k="name" placeholder="Name" value="${esc(t.name||'')}"><input data-k="price" type="number" min="0" step="0.01" placeholder="Price" value="${esc(t.price??'')}"><select data-k="status"><option ${t.status==='draft'?'selected':''}>draft</option><option ${!t.status||t.status==='active'?'selected':''}>active</option><option ${t.status==='inactive'?'selected':''}>inactive</option><option ${t.status==='sold_out'?'selected':''}>sold_out</option></select><input data-k="external_url" placeholder="External ticket URL" value="${esc(t.external_url||'')}"><button type="button" class="icon" onclick="this.parentElement.remove()">×</button>`;$('#tickets').appendChild(d)}
function ticketPayload(row,eventId,i){const o={event_id:eventId,sort_order:i};row.querySelectorAll('[data-k]').forEach(el=>o[el.dataset.k]=el.value);return o}
async function saveEvent(){const payload={title:$('#e_title').value.trim(),slug:$('#e_slug').value.trim(),description:$('#e_description').value,cover_image:$('#e_cover_image').value,accent:$('#e_accent').value,featured:Number($('#e_featured').value),event_date:$('#e_event_date').value.replace('T',' '),city:$('#e_city').value.trim(),venue:$('#e_venue').value.trim(),archive_year:Number($('#e_archive_year').value)||null,status:$('#e_status').value,ticket_instructions:$('#e_ticket_instructions').value,ticket_qr:$('#e_ticket_qr').value,ticket_url:$('#e_ticket_url').value};if(!payload.title||!payload.event_date||!payload.city){msg('Name, date and city are required.',false,'eventNotice');return}if(!csrf){msg('Security token unavailable. Reload the page.',false,'eventNotice');return}try{const path=currentEvent?'/events/'+currentEvent.id:'/events';const j=await api(path,{method:currentEvent?'PUT':'POST',body:JSON.stringify(payload),headers:{'X-CSRF-Token':csrf}});if(j.ok===false)throw new Error(j.error||'Save failed');const id=Number(j.id||j.data?.id||currentEvent?.id);if(!id)throw new Error('Event ID missing after save');await saveTickets(id);currentEvent={...(currentEvent||{}),id,...payload};await loadEvents();msg('Event saved.')}catch(e){msg('Save failed: '+e.message,false,'eventNotice')}}
async function saveTickets(eventId){const rows=$$('#tickets .ticket-row');const keep=new Set();for(let i=0;i<rows.length;i++){const row=rows[i],p=ticketPayload(row,eventId,i),existing=Number(row.dataset.id||0);let j;if(existing){keep.add(existing);j=await api('/ticket_types/'+existing,{method:'PUT',body:JSON.stringify(p),headers:{'X-CSRF-Token':csrf}})}else{j=await api('/ticket_types',{method:'POST',body:JSON.stringify(p),headers:{'X-CSRF-Token':csrf}});if(j.id)row.dataset.id=String(j.id)}if(j.ok===false)throw new Error(j.error||'Ticket save failed')}const old=(currentEvent?.ticket_types||[]).map(t=>Number(t.id)).filter(Boolean);for(const id of old){if(!keep.has(id)){const j=await api('/ticket_types/'+id,{method:'DELETE',headers:{'X-CSRF-Token':csrf}});if(j.ok===false)throw new Error(j.error||'Ticket delete failed')}}currentEvent.ticket_types=rows.map((row,i)=>{const p=ticketPayload(row,eventId,i);return {...p,id:Number(row.dataset.id||0)}})}
async function loadArtists(){try{const j=await api('/artists');artists=j.data||j.artists||[];renderRoster();renderEventArtists()}catch(e){msg('Could not load artists: '+e.message,false)}}
function renderRoster(){const q=($('#artistSearch').value||'').toLowerCase();const a=artists.filter(x=>JSON.stringify(x).toLowerCase().includes(q));$('#rosterList').innerHTML=a.map(x=>`<div class="artist"><div class="ph">${x.photo?'IMG':'BRV'}</div><div class="grow"><b>${esc(x.name)}</b><small>${esc(x.collective_status||'none')} · order ${esc(x.collective_order??'—')}</small></div><button class="icon" onclick="editArtist(${Number(x.id)})">EDIT</button></div>`).join('')||'<div class="empty">No artists found.</div>'}
function editArtist(id){const a=artists.find(x=>Number(x.id)===Number(id));if(!a)return;$('#artistDetail').innerHTML=`<div class="field"><label>Artist</label><input value="${esc(a.name)}" disabled></div><div class="field"><label>Collective status</label><select id="a_status"><option ${a.collective_status==='none'?'selected':''}>none</option><option ${a.collective_status==='active'?'selected':''}>active</option><option ${a.collective_status==='alumni'?'selected':''}>alumni</option></select></div><div class="field"><label>Collective order</label><input id="a_order" type="number" value="${esc(a.collective_order??0)}"></div><div class="field"><label>Joined at</label><input id="a_joined" type="date" value="${esc((a.collective_joined_at||'').slice(0,10))}"></div><div class="field"><label>Left at</label><input id="a_left" type="date" value="${esc((a.collective_left_at||'').slice(0,10))}"></div><button class="btn red" onclick="saveArtist(${id})">SAVE ARTIST</button>`}
async function saveArtist(id){if(!csrf){msg('Security token unavailable. Reload the page.',false);return}try{const p={collective_status:$('#a_status').value,collective_order:Number($('#a_order').value)||0,collective_joined_at:$('#a_joined').value||null,collective_left_at:$('#a_left').value||null};const j=await api('/artists/'+id,{method:'PUT',body:JSON.stringify(p),headers:{'X-CSRF-Token':csrf}});if(j.ok===false)throw new Error(j.error||'Save failed');await loadArtists();msg('Artist lifecycle updated.')}catch(e){msg('Artist save failed: '+e.message,false)}}
function renderEventArtists(){if(!artists.length){$('#eventArtists').innerHTML='<div class="empty">Load artists to manage event participation.</div>';return}const selected=new Set((currentEvent?.artists||currentEvent?.event_artists||currentEvent?.lineup||[]).map(x=>Number(x.artist_id||x.id)));$('#eventArtists').innerHTML=artists.filter(a=>a.collective_status==='active'||selected.has(Number(a.id))).map(a=>`<div class="artist"><div class="ph">${a.photo?'IMG':'BRV'}</div><div class="grow"><b>${esc(a.name)}</b><small>${esc(a.collective_status||'none')}</small></div><input type="checkbox" data-artist="${Number(a.id)}" ${selected.has(Number(a.id))?'checked':''}></div>`).join('')}
$$('.tab').forEach(t=>t.onclick=()=>{$$('.tab').forEach(x=>x.classList.remove('active'));t.classList.add('active');const roster=t.dataset.tab==='roster';$('#eventsTab').style.display=roster?'none':'block';$('#rosterTab').style.display=roster?'block':'none';if(roster)loadArtists()});$('#eventSearch').oninput=renderEvents;$('#artistSearch').oninput=renderRoster;
(async()=>{try{await initAuth();await loadEvents();}catch(e){msg('Initialization failed: '+e.message,false)}})();
</script>
</body></html>